#include <deque>
#include <iostream>

template <class T, class Allocator>
bool operator!=(const std::deque<T, Allocator>& x, const std::deque<T, Allocator>& y) {
    if (x.size() != y.size()) return true;
    for (size_t i = 0; i < x.size(); ++i) {
        if (x[i] != y[i]) return true;
    }
    return false;
}

int main() {
    std::deque<int> d1 = {1, 2, 3};
    std::deque<int> d2 = {1, 2, 4};
    if (operator!=(d1, d2)) {
        std::cout << "Deques are not equal." << std::endl;
    } else {
        std::cout << "Deques are equal." << std::endl;
    }
    return 0;
}
